s=s[:i]+'''/**
 * Walks one tenant's live projects, issues and comments and re-upserts every
 * document, after clearing the tenant's existing entries. Only live content
 * is indexed: a project's issues and comments need the project live too.
 * Every page is walked, however large the tenant is.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    await searchRepo.deleteSearchDocumentsForOrg(orgId);

    const liveProjects = new Set<string>();
    let projectCursor: string | null = null;
    do {
      const page: Page<Project> = await projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor: projectCursor,
        includeArchived: false,
      });
      for (const project of page.items) {
        try {
          await indexProject(orgId, project);
          liveProjects.add(project.id);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
      projectCursor = page.nextCursor;
    } while (projectCursor);

    let issueCursor: string | null = null;
    do {
      const page: Page<Issue> = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: issueCursor,
        includeArchived: false,
      });
      for (const issue of page.items) {
        if (!liveProjects.has(issue.projectId)) continue;
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;

          let commentCursor: string | null = null;
          do {
            const comments: Page<Comment> = await commentRepo.listComments({
              orgId,
              issueId: issue.id,
              includeArchived: false,
              limit: PAGE_SIZE,
              cursor: commentCursor,
            });
            for (const comment of comments.items) {
              await indexComment(orgId, comment);
              result.processed += 1;
            }
            commentCursor = comments.nextCursor;
          } while (commentCursor);
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
      issueCursor = page.nextCursor;
    } while (issueCursor);
  });
}
